// Resource requiring delete[] cleanup, not default delete
int* raw_array = new int[10];

// Custom deleter (lambda) passed as the second argument
std::shared_ptr<int> array_manager(
    raw_array,
    [](int* p) { delete[] p; }
);

// Function Pointer Deleter Example
void file_closer(FILE* f) { if (f) fclose(f); }
std::shared_ptr<FILE> log_file(
    fopen("log.txt", "w"),
    file_closer
);

// Deleter stored as part of the shared_ptr type (Stateful/Functor)
struct SocketCloser {
    void operator()(int* sock) const { close_socket(*sock); delete sock; }
};
std::shared_ptr<int> socket_handle(new int(123), SocketCloser{});
